@block Se begin
    @ports p::Power{Generic}
    @parameters e::Real = 1.0, [unit = "effort", description = "Effort value"]
    @equations p.e ~ e
    @causality p => (:effort_out, :fixed)
end

@block Sf begin
    @ports p::Power{Generic}
    @parameters f::Real = 1.0, [unit = "flow", description = "Flow value"]
    @equations p.f ~ f
    @causality p => (:flow_out, :fixed)
end

@block MSe begin
    @ports p::Power{Generic}
    @inputs u::Real
    @parameters gain::Real = 1.0, [unit = "effort", description = "Effort gain on the input"]
    @equations p.e ~ gain * u
    @causality p => (:effort_out, :fixed)
end

@block C begin
    @ports p::Power{Generic}
    @parameters c::Real = 1.0, [unit = "flow*s/effort", min = 0, description = "Compliance"]
    @variables q::Real = 0.0, [unit = "flow*s", state = :prefer, description = "Displacement"]
    @equations begin
        ddt(q) ~ p.f
        p.e ~ q / c
    end
    @causality p => :effort_out
end

@block I begin
    @ports p::Power{Generic}
    @parameters i::Real = 1.0, [unit = "effort*s/flow", min = 0, description = "Inertia"]
    @variables P::Real = 0.0, [unit = "effort*s", state = :prefer, description = "Momentum"]
    @equations begin
        ddt(P) ~ p.e
        p.f ~ P / i
    end
    @causality p => :flow_out
end

@block R begin
    @ports p::Power{Generic}
    @parameters r::Real = 1.0, [unit = "effort/flow", min = 0, description = "Resistance"]
    @equations p.e ~ r * p.f
end

@block TF begin
    @ports begin
        p1::Power{Generic}
        p2::Power{Generic}
    end
    @parameters n::Real = 1.0, [min = 0, description = "Transformer modulus"]
    @equations begin
        # Power-positive-into-each-port (spec): e1*f1 + e2*f2 = 0, so one flow is negative.
        p1.e ~ n * p2.e
        p2.f ~ -n * p1.f
    end
    @causality (p1, p2) => :transformer
end

@block GY begin
    @ports begin
        p1::Power{Generic}
        p2::Power{Generic}
    end
    @parameters r::Real = 1.0, [unit = "effort/flow", description = "Gyrator modulus"]
    @equations begin
        # Power-positive-into-each-port (spec): e1*f1 + e2*f2 = 0, so one effort is negative.
        # With p1 on the electrical side and p2 on the mechanical side (the DC-motor bond graph
        # of plan 9.1), this orientation is the motor one: p1.e is the back-EMF term and
        # p2.e = r*p1.f is the torque delivered to the shaft.
        p1.e ~ -r * p2.f
        p2.e ~ r * p1.f
    end
    @causality (p1, p2) => :gyrator
end

@block De begin
    @ports p::Power{Generic}
    @outputs y::Real
    @equations begin
        p.f ~ 0.0
        y ~ p.e
    end
    @causality p => (:effort_out, :fixed)
end

@block Df begin
    @ports p::Power{Generic}
    @outputs y::Real
    @equations begin
        p.e ~ 0.0
        y ~ p.f
    end
    @causality p => (:flow_out, :fixed)
end

@block Constant begin
    @outputs y::Real
    @parameters value::Real = 1.0, [description = "Output value"]
    @equations y ~ value
end

@block Step begin
    @outputs y::Real
    @parameters begin
        t_step::Real = 1.0, [unit = "s", min = 0, description = "Step time"]
        initial::Real = 0.0, [description = "Value before the step"]
        final::Real = 1.0, [description = "Value after the step"]
    end
    @equations y ~ ifelse(t >= t_step, final, initial)
end

@block Sine begin
    @outputs y::Real
    @parameters begin
        amplitude::Real = 1.0, [description = "Amplitude"]
        frequency::Real = 1.0, [unit = "rad/s", description = "Angular frequency"]
        phase::Real = 0.0, [unit = "rad", description = "Phase"]
        offset::Real = 0.0, [description = "Offset"]
    end
    @equations y ~ offset + amplitude * sin(frequency * t + phase)
end

@block Gain begin
    @inputs u::Real
    @outputs y::Real
    @parameters k::Real = 1.0, [description = "Gain"]
    @equations y ~ k * u
end

@block Sum begin
    @constants N::Int = 2
    @inputs u::Vec{N}
    @outputs y::Real
    @parameters signs::Vec{N} = [1.0, 1.0], [description = "Sign of every input, +1 or -1"]
    @equations y ~ dot(signs, u)
end

@block Integrator begin
    @inputs u::Real
    @outputs y::Real
    @parameters begin
        lower::Real = -1e30, [description = "Lower saturation limit (1e30 means none)"]
        upper::Real = 1e30, [description = "Upper saturation limit (1e30 means none)"]
    end
    @variables x::Real = 0.0, [state = :prefer, description = "Integrator state"]
    @equations begin
        ddt(x) ~ u
        y ~ clamp(x, lower, upper)
    end
end

@block PIController begin
    @parameters begin
        Kp::Real = 1.0, [tunable = true, description = "Proportional gain"]
        Ti::Real = 0.1, [unit = "s", min = 0, tunable = true, description = "Integral time"]
    end
    @inputs e::Real
    @outputs u::Real
    @variables x::Real = 0.0, [state = :prefer, description = "Integral state"]
    @equations begin
        ddt(x) ~ e / Ti
        u ~ Kp * (e + x)
    end
end

@block Resistor begin
    @ports begin
        p::Power{Electrical}
        n::Power{Electrical}
    end
    @parameters R::Real = 1000.0, [unit = "Ohm", min = 0, description = "Resistance"]
    @equations begin
        p.f + n.f ~ 0.0
        p.e - n.e ~ R * p.f
    end
end

@block Capacitor begin
    @ports begin
        p::Power{Electrical}
        n::Power{Electrical}
    end
    @parameters C::Real = 1e-6, [unit = "F", min = 0, description = "Capacitance"]
    @variables v::Real = 0.0, [unit = "V", state = :prefer, description = "Voltage across the capacitor"]
    @equations begin
        p.f + n.f ~ 0.0
        ddt(v) ~ p.f / C
        p.e - n.e ~ v
    end
end

@block Inductor begin
    @ports begin
        p::Power{Electrical}
        n::Power{Electrical}
    end
    @parameters L::Real = 1e-3, [unit = "H", min = 0, description = "Inductance"]
    @variables i::Real = 0.0, [unit = "A", state = :prefer, description = "Current through the inductor"]
    @equations begin
        p.f + n.f ~ 0.0
        ddt(i) ~ (p.e - n.e) / L
        p.f ~ i
    end
end

@block Ground begin
    @ports p::Power{Electrical}
    @equations p.e ~ 0.0
    @causality p => (:effort_out, :fixed)
end

@block VoltageSource begin
    @ports begin
        p::Power{Electrical}
        n::Power{Electrical}
    end
    @inputs u::Real
    @parameters V::Real = 1.0, [unit = "V", description = "Voltage gain on the control input"]
    @equations begin
        p.e - n.e ~ V * u
        p.f + n.f ~ 0.0
    end
end

@block Mass begin
    @ports begin
        a::Power{Translation}
        b::Power{Translation}
    end
    @parameters m::Real = 1.0, [unit = "kg", min = 0, description = "Mass"]
    @variables begin
        x::Real = 0.0, [unit = "m", state = :prefer, description = "Relative position"]
        v::Real = 0.0, [unit = "m/s", state = :prefer, description = "Relative velocity"]
    end
    @equations begin
        v ~ a.f - b.f
        ddt(x) ~ v
        a.e ~ m * ddt(v)
        b.e ~ -a.e
    end
end

@block Spring begin
    @ports begin
        a::Power{Translation}
        b::Power{Translation}
    end
    @parameters begin
        k::Real = 1000.0, [unit = "N/m", min = 0, description = "Stiffness"]
        x_free::Real = 0.0, [unit = "m", description = "Free length"]
    end
    @variables x::Real = 0.0, [unit = "m", state = :prefer, description = "Relative displacement"]
    @equations begin
        ddt(x) ~ a.f - b.f
        a.e ~ k * (x - x_free)
        b.e ~ -a.e
    end
end

@block Damper begin
    @ports begin
        a::Power{Translation}
        b::Power{Translation}
    end
    @parameters d::Real = 10.0, [unit = "N*s/m", min = 0, description = "Damping coefficient"]
    @equations begin
        a.e ~ d * (a.f - b.f)
        b.e ~ -a.e
    end
end

@block Fixed begin
    @ports a::Power{Translation}
    @equations a.f ~ 0.0
    @causality a => (:flow_out, :fixed)
end

@block ForceSource begin
    @ports begin
        a::Power{Translation}
        b::Power{Translation}
    end
    @inputs u::Real
    @parameters F::Real = 1.0, [unit = "N", description = "Force gain on the control input"]
    @equations begin
        a.e ~ F * u
        b.e ~ -a.e
    end
end

@block Inertia begin
    @ports begin
        a::Power{Rotation}
        b::Power{Rotation}
    end
    @parameters J::Real = 0.01, [unit = "kg*m^2", min = 0, description = "Moment of inertia"]
    @variables begin
        phi::Real = 0.0, [unit = "rad", state = :prefer, description = "Relative angle"]
        w::Real = 0.0, [unit = "rad/s", state = :prefer, description = "Relative angular velocity"]
    end
    @equations begin
        w ~ a.f - b.f
        ddt(phi) ~ w
        a.e ~ J * ddt(w)
        b.e ~ -a.e
    end
end

@block TorsionSpring begin
    @ports begin
        a::Power{Rotation}
        b::Power{Rotation}
    end
    @parameters begin
        k::Real = 10.0, [unit = "N*m/rad", min = 0, description = "Torsional stiffness"]
        phi_free::Real = 0.0, [unit = "rad", description = "Free angle"]
    end
    @variables phi::Real = 0.0, [unit = "rad", state = :prefer, description = "Relative angle"]
    @equations begin
        ddt(phi) ~ a.f - b.f
        a.e ~ k * (phi - phi_free)
        b.e ~ -a.e
    end
end

@block RotationalDamper begin
    @ports begin
        a::Power{Rotation}
        b::Power{Rotation}
    end
    @parameters d::Real = 1e-3, [unit = "N*m*s/rad", min = 0, description = "Damping coefficient"]
    @equations begin
        a.e ~ d * (a.f - b.f)
        b.e ~ -a.e
    end
end

@block FixedShaft begin
    @ports a::Power{Rotation}
    @equations a.f ~ 0.0
    @causality a => (:flow_out, :fixed)
end

@block TorqueSource begin
    @ports begin
        a::Power{Rotation}
        b::Power{Rotation}
    end
    @inputs u::Real
    @parameters T::Real = 1.0, [unit = "N*m", description = "Torque gain on the control input"]
    @equations begin
        a.e ~ T * u
        b.e ~ -a.e
    end
end

@block IdealGear begin
    @ports begin
        a::Power{Rotation}
        b::Power{Rotation}
    end
    @parameters n::Real = 1.0, [min = 0, description = "Gear ratio (a.f = n * b.f)"]
    @equations begin
        a.f ~ n * b.f
        b.e ~ -n * a.e
    end
    @causality (a, b) => :transformer
end

@block SpeedSensor begin
    @ports a::Power{Rotation}
    @outputs y::Real = 0.0, [unit = "rad/s"]
    @equations begin
        a.e ~ 0.0
        y ~ a.f
    end
    @causality a => (:effort_out, :fixed)
end

@block AngleSensor begin
    @ports a::Power{Rotation}
    @outputs y::Real = 0.0, [unit = "rad"]
    @variables phi::Real = 0.0, [unit = "rad", state = :prefer, description = "Sensed angle"]
    @equations begin
        a.e ~ 0.0
        ddt(phi) ~ a.f
        y ~ phi
    end
    @causality a => (:effort_out, :fixed)
end
